#![allow(dead_code, unused_parens, unconditional_panic)]

#[no_mangle]
pub extern "C" fn plain_sum_u32(a: u32, b: u32) -> u32 { a + b }

#[no_mangle]
pub extern "C" fn wrapping_sum_u32(a: u32, b: u32) -> u32 { a.wrapping_add(b) }

#[no_mangle]
pub extern "C" fn plain_product_u64(a: u64, b: u64) -> u64 { a * b }

#[no_mangle]
pub extern "C" fn wrapping_product_u64(a: u64, b: u64) -> u64 { a.wrapping_mul(b) }

#[no_mangle]
pub extern "C" fn plain_negate_i32(a: i32) -> i32 { -a }

#[no_mangle]
pub extern "C" fn wrapping_negate_i32(a: i32) -> i32 { a.wrapping_neg() }

#[no_mangle]
pub extern "C" fn plain_left_shift_u32(a: u32, b: u32) -> u32 { a << b }

#[no_mangle]
pub extern "C" fn wrapping_left_shift_u32(a: u32, b: u32) -> u32 { a.wrapping_shl(b) }

#[no_mangle]
pub extern "C" fn guarded_left_shift_u32(a: u32, b: u32) -> u32 { if b < 32 { a.wrapping_shl(b) } else { 0 } }

#[no_mangle]
pub extern "C" fn plain_right_shift_i32(a: i32, b: u32) -> i32 { a.wrapping_shr(b) }

#[no_mangle]
pub extern "C" fn plain_quotient_u32(a: u32, b: u32) -> u32 { a / b }

#[no_mangle]
pub extern "C" fn plain_remainder_u32(a: u32, b: u32) -> u32 { a % b }

#[no_mangle]
pub extern "C" fn plain_quotient_i32(a: i32, b: i32) -> i32 { a / b }

#[no_mangle]
pub extern "C" fn unchecked_quotient_u32(a: u32, b: u32) -> u32 { unsafe { a.unchecked_div(b) } }

#[no_mangle]
pub extern "C" fn unchecked_quotient_i32(a: i32, b: i32) -> i32 { unsafe { a.unchecked_div(b) } }

#[no_mangle]
pub extern "C" fn unchecked_remainder_u32(a: u32, b: u32) -> u32 { unsafe { a.unchecked_rem(b) } }

#[no_mangle]
pub extern "C" fn widen_u8_to_u32(a: u8) -> u32 { a as u32 }

#[no_mangle]
pub extern "C" fn narrow_u32_to_u8(a: u32) -> u8 { a as u8 }

#[no_mangle]
pub extern "C" fn sign_extend_i8_to_i64(a: i8) -> i64 { a as i64 }

#[no_mangle]
pub extern "C" fn sum_u128(a: u128, b: u128) -> u128 { a.wrapping_add(b) }

#[no_mangle]
pub extern "C" fn quotient_u128_from_u64(a: u64, b: u64) -> u64 { unsafe { ((a as u128).unchecked_div(b as u128)) as u64 } }

#[no_mangle]
pub extern "C" fn sum_f64(a: f64, b: f64) -> f64 { a + b }

#[no_mangle]
pub extern "C" fn sum_f32(a: f32, b: f32) -> f32 { a + b }

#[no_mangle]
pub extern "C" fn f64_bits(a: f64) -> u64 { a.to_bits() }

#[no_mangle]
pub extern "C" fn bits_f64(a: u64) -> f64 { f64::from_bits(a) }

#[no_mangle]
pub extern "C" fn saturating_f64_to_i64(a: f64) -> i64 { a as i64 }

#[no_mangle]
pub extern "C" fn truncating_f64_to_i64(a: f64) -> i64 { unsafe { a.to_int_unchecked::<i64>() } }

#[no_mangle]
pub extern "C" fn i64_to_f64(a: i64) -> f64 { a as f64 }

#[no_mangle]
pub extern "C" fn u64_to_f64(a: u64) -> f64 { a as f64 }

#[no_mangle]
pub extern "C" fn f64_to_f32(a: f64) -> f32 { a as f32 }

#[no_mangle]
pub extern "C" fn choose_u32(c: u32, a: u32, b: u32) -> u32 { if (c & 1) != 0 { a } else { b } }

#[no_mangle]
pub extern "C" fn less_signed_i32(a: i32, b: i32) -> u32 { if a < b { 1 } else { 0 } }

#[no_mangle]
pub extern "C" fn less_unsigned_u32(a: u32, b: u32) -> u32 { if a < b { 1 } else { 0 } }

#[no_mangle]
pub extern "C" fn complement_u32(a: u32) -> u32 { !a }

#[no_mangle]
pub extern "C" fn f16_exists(a: u16) -> u16 { a }

#[no_mangle]
pub extern "C" fn wide_arrival_u8(a: u8, b: u8) -> u8 { a.wrapping_add(b) }

